/** Province names, for the first dropdown. */
function ph_provinces(): array
{
    return array_keys(ph_locations());
}

/** Cities for one province, or [] when the province is not recognised. */
function ph_cities(string $province): array
{
    return ph_locations()[$province] ?? [];
}

/** True when $city genuinely belongs to $province. */
function ph_is_valid_city(string $province, string $city): bool
{
    return in_array($city, ph_cities($province), true);
}
